import CADCore
import Foundation
import Testing
@testable import CADKernel

/// OpenCascade's fillet can fault outright (a null curve inside the blend) on some geometry, and a fault is no C++
/// exception: it took the whole app down. The fillet and chamfer builders now run under a guard that turns the fault
/// into an ordinary failed round.
@Suite struct RoundFaultGuardTests {
    /// The dark base of a shoe sole (rounded plan corners, side coves, a pair of feet cut out) with the 0.6 mm slit
    /// cut through it that splits the sole in two: features of a real model, which a 4 mm round of either of the edges
    /// below used to bring down the app on.
    private let edges = ["base.end|base.side.bs_a.3", "base.side.bs_a.3|base_round.side.63937b25"]

    private func slitBase() throws -> CADDocument {
        try CADDocument.decode(Data(baseSlitJSON.utf8))
    }

    @Test func aRoundThatFaultsInsideOpenCascadeFailsInsteadOfCrashing() throws {
        let doc = try slitBase()
        let before = Regenerator.regenerate(doc)
        #expect(before.errors.isEmpty, "\(before.errors)")
        let base = try #require(before.body("base"))
        for edge in edges {
            #expect(base.hasEdge(edge), "the edge \(edge) exists")
            var d = doc
            d.features.append(Feature(id: "fx", name: "Fillet2", .fillet(EdgeFeature(edges: [EdgeRef(body: "base", edge: edge)], size: "4 mm"))))
            let r = Regenerator.regenerate(d)  // reaching the next line is the test: it used to be a segmentation fault
            if let why = r.errors["fx"] {
                #expect(!why.isEmpty, "a failed round says why")
            } else {
                #expect(r.body("base") != nil, "the round built")
            }
            #expect(r.errors.keys.allSatisfy { $0 == "fx" }, "nothing else broke: \(r.errors)")
        }
    }

    @Test func theKernelStillRoundsAfterAFault() throws {
        let doc = try slitBase()
        var faulting = doc
        faulting.features.append(Feature(id: "fx", name: "Fillet2", .fillet(EdgeFeature(edges: [EdgeRef(body: "base", edge: edges[0])], size: "4 mm"))))
        _ = Regenerator.regenerate(faulting)
        // Another round on the same sole, afterwards, on a thread that has seen the fault.
        var plain = doc
        plain.features.append(Feature(id: "fy", name: "Fillet3", .fillet(EdgeFeature(edges: [EdgeRef(body: "base", edge: "base.start|base_round.side.bb1de989")], size: "1 mm"))))
        let r = Regenerator.regenerate(plain)
        #expect(r.body("base") != nil)
        #expect(r.errors["fy"] == nil || !(r.errors["fy"]!.contains("OpenCascade failed inside")), "\(r.errors)")
    }

